WITH base AS (SELECT *, DATE_ADD(hire_date, 37) hire_date_plus_37d, LOWER(job_title) job_title_lower FROM employees WHERE hire_date >= DATE '2023-03-11'), with_dims AS (SELECT s.*, b.salary AS employee_salary, b.full_name AS employee_full_name FROM base s LEFT JOIN employees b ON s.manager_id = b.id WHERE b.is_remote), metrics AS (SELECT id, full_name, dept_id, salary, hire_date, level, hire_date_plus_37d, job_title_lower, CUME_DIST() OVER (PARTITION BY DATE_TRUNC('month', hire_date) ORDER BY salary) salary_cume_dist, RANK() OVER (PARTITION BY job_title ORDER BY salary) salary_rank, LAST_VALUE(level) IGNORE NULLS OVER (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_level FROM with_dims), with_dims_employees AS (SELECT src.id, src.full_name, src.dept_id, src.hire_date, src.job_title_lower, src.salary_rank, d.dept_name, d.budget, d.location FROM metrics src INNER JOIN departments d ON src.dept_id = d.id), scored AS (SELECT *, LAST_VALUE(dept_name) IGNORE NULLS OVER (PARTITION BY dept_name ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_dept_name, LAG(budget, 1) OVER (PARTITION BY location, dept_id ORDER BY budget, id) prev_budget FROM with_dims_employees), summary AS (SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, SIZE(COLLECT_SET(location)) AS num_locations, PERCENTILE_APPROX(prev_budget, ARRAY(0.25, 0.5, 0.75)) AS prev_budget_quartiles, COUNT(*) AS cnt, AVG(salary_rank) FILTER (WHERE location = 'Chiang Mai') AS chiang_mai_avg_salary_rank FROM scored GROUP BY activity_month HAVING num_locations >= 1) SELECT activity_month, num_locations, prev_budget_quartiles, cnt, chiang_mai_avg_salary_rank FROM summary ORDER BY activity_month;
